wchar_t * CDECL _wgetenv(const wchar_t *name)
{
    wchar_t *ret;

    if (!MSVCRT_CHECK_PMT(name != NULL)) return NULL;

    _lock(_ENV_LOCK);
    ret = wgetenv_helper(name);
    _unlock(_ENV_LOCK);
    return ret;
